    {
        var path = "/contacts";
        var query = new Query().Add("search", search).Add("tags", tags).Add("tags_match", tagsMatch).Add("groups", groups).Add("project_id", projectId).Add("instance_id", instanceId).Add("status", status).Add("city", city).Add("state", state).Add("country", country).Add("zip", zip).Add("document", document).Add("has_email", hasEmail).Add("last_activity_after", lastActivityAfter).Add("last_activity_before", lastActivityBefore).Add("created_after", createdAfter).Add("created_before", createdBefore).Add("sort", sort).Add("limit", limit).Add("offset", offset);
